import{_ as a,c as e,o,a4 as l}from"./chunks/framework.4aTu-Nia.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/原则.md","filePath":"books/原则.md"}'),t={name:"books/原则.md"},i=l('<p>#瑞·达利欧</p><blockquote><p>在生活原则部分，他认为要遵照<strong>目标—问题—诊断—方案—践行</strong>的五步流程原则，同时需保持头脑的极度开放，拥有理解他人不同于自己的换位思考、正视自身弱点以及不断进化自我的能力。所谓“不进化就死亡”，瑞·达利欧相信：进化是生命最大的成就和最大的回报。</p></blockquote><blockquote><p>用行动验证原则。瑞·达利欧的所有原则，无一不是基于实践性及可操作性。</p></blockquote><blockquote><p>除非你意识到你的潜意识，否则潜意识将主导你的人生，而你将其称为命运。</p></blockquote><h2 id="冒险" tabindex="-1">冒险 <a class="header-anchor" href="#冒险" aria-label="Permalink to &quot;冒险&quot;">​</a></h2><p>少一次冒险，人生少一分精彩</p><p>平稳与冒险的选择，只要能付清生活开支，就选择去冒险</p><p>你的生活原则、工作原则有哪些？</p><p>保持极度透明，通过透明寻找正义。</p><p>如果不愿当面批评别人，也不要背后。没有理由背后议论别人，只会产生坏的效果。</p><h2 id="管理" tabindex="-1">管理 <a class="header-anchor" href="#管理" aria-label="Permalink to &quot;管理&quot;">​</a></h2><p>出色的管理者，注重协调，而非亲力亲为</p><ol><li>把员工管理好</li><li>下沉去做本不该自己做，但下属做不好的事</li><li>把管理不好的领域，提升给上级管理</li></ol><p>只想着授权给别人做事挺危险的</p><p>了解别人工作的动力</p><p>明确职责，消除含糊的预期</p><p>强迫自己和员工做困难的事，这是一项自然法则。利用痛苦激发高质量思考，管理痛苦。</p><p>问责过程透明</p><p>谁承担总体责任</p><h2 id="习惯" tabindex="-1">习惯 <a class="header-anchor" href="#习惯" aria-label="Permalink to &quot;习惯&quot;">​</a></h2><ol><li>信号</li><li>行为</li><li>奖励</li></ol><p>决策机器，系统化，有证据、原则支撑。把最重要原则习惯化。打造机器可能要花两倍时间，但长期回报合理。</p><h2 id="预测" tabindex="-1">预测 <a class="header-anchor" href="#预测" aria-label="Permalink to &quot;预测&quot;">​</a></h2><p>试炼之路</p><p>最重要的事情不是预知未来，而是知道在每一个时间点上如何针对可获得的信息做出合理的回应</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p>根据预期价值做决策（= 预期收益 * 损失概率 - 预期损失 * 损失概率）</p><p>想要改进你的决策，你能做的最有价值的事情之一，是深入思考你的决策原则，同时以文字和计算机算法的形式把这些原则写下来，在条件允许的情况下进行返回测试，并以实时的方式，在用你的头脑进行决策的同时运用这些原则。</p><h2 id="塑造者特征" tabindex="-1">塑造者特征 <a class="header-anchor" href="#塑造者特征" aria-label="Permalink to &quot;塑造者特征&quot;">​</a></h2><ul><li>极富好奇心，有把事情弄清楚的强烈冲动</li><li>近乎叛逆的独立思考</li><li>需要宏大别致的梦想</li><li>务实并坚毅地排除万难，实现目标</li><li>了解自己和他人的长处和短处，所以能协调团队来实现目标</li></ul><p>[[Principles-For-Success-Video]]</p>',31),p=[i];function r(s,c,n,h,d,_){return o(),e("div",null,p)}const q=a(t,[["render",r]]);export{b as __pageData,q as default};
